using System;
using System.IO;
using UnityEditor;
using UnityEditor.Events;
using UnityEngine;
using UnityEngine.UI;
using static ScrewKing.Editor.UiPrefabBuilder;

namespace ScrewKing.Editor
{
    // One-time migration of the old empty HUD. Existing authored assets are never regenerated by a build.
    public static class GameplayHudPrefabBuilder
    {
        public const string Widgets=Folder+"/Widgets";
        const string PalettePath="Assets/ScrewKing/Resources/UI/HudPalette.asset";
        static ScrewKingHudPalette palette;
        public static void Ensure()
        {
            var asset=AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/GameplayHUD.prefab");
            if(asset && asset.GetComponent<ScrewKingGameplayHud>().IsAuthored){
                if(!asset.GetComponent<ScrewKingGameplayHud>().ProgressFill.sprite){
                    var loaded=PrefabUtility.LoadPrefabContents(Folder+"/GameplayHUD.prefab");
                    try{loaded.GetComponent<ScrewKingGameplayHud>().ProgressFill.sprite=SolidSprite();PrefabUtility.SaveAsPrefabAsset(loaded,Folder+"/GameplayHUD.prefab");}
                    finally{PrefabUtility.UnloadPrefabContents(loaded);}
                }
                return;
            }
            // Preserve nonempty designer layouts even if a binding was removed; validation reports it instead of rebuilding.
            if(asset && asset.transform.childCount>0)return;
            Directory.CreateDirectory(Widgets);AssetDatabase.Refresh();palette=GetPalette();
            Save("HudBox",()=>Box("HudBox",false));Save("HudClosingBox",()=>Box("HudClosingBox",true));
            Save("HudBufferSlot",Buffer);Save("HudFlyingScrew",Flight);Save("HudGuide",Guide);
            Save("HudBoosterSlot",()=>Booster("HudBoosterSlot","Layer 35","ADD SLOT",ScrewKingUiCommand.AddSlot));
            Save("HudBoosterClear",()=>Booster("HudBoosterClear","Layer 33","CLEAR SLOT",ScrewKingUiCommand.ClearSlots));
            Save("HudBoosterHammer",()=>Booster("HudBoosterHammer","Layer 34","GLASS HAMMER",ScrewKingUiCommand.GlassHammer));
            bool existing=asset;
            var root=existing?PrefabUtility.LoadPrefabContents(Folder+"/GameplayHUD.prefab"):new GameObject("GameplayHUD",typeof(RectTransform),typeof(ScrewKingGameplayHud));
            try{
                if(!existing)Center(root.GetComponent<RectTransform>());
                Build(root.GetComponent<ScrewKingGameplayHud>());
                PrefabUtility.SaveAsPrefabAsset(root,Folder+"/GameplayHUD.prefab");
            }finally{if(existing)PrefabUtility.UnloadPrefabContents(root);else UnityEngine.Object.DestroyImmediate(root);}
            AssetDatabase.SaveAssets();
        }
        static Sprite SolidSprite()
        {
            const string path="Assets/ScrewKing/Resources/UI/HudSolid.asset";
            foreach(var item in AssetDatabase.LoadAllAssetsAtPath(path))if(item is Sprite sprite)return sprite;
            var texture=new Texture2D(2,2,TextureFormat.RGBA32,false){name="HUD White",filterMode=FilterMode.Point,wrapMode=TextureWrapMode.Clamp};
            texture.SetPixels(new[]{Color.white,Color.white,Color.white,Color.white});texture.Apply();AssetDatabase.CreateAsset(texture,path);
            var result=Sprite.Create(texture,new Rect(0,0,2,2),new Vector2(.5f,.5f),100);result.name="White";AssetDatabase.AddObjectToAsset(result,texture);AssetDatabase.SaveAssets();return result;
        }
        static ScrewKingHudPalette GetPalette()
        {
            var p=AssetDatabase.LoadAssetAtPath<ScrewKingHudPalette>(PalettePath);if(p)return p;
            p=ScriptableObject.CreateInstance<ScrewKingHudPalette>();p.Screws=new Sprite[12];p.Boxes=new Sprite[12];p.Lids=new Sprite[12];
            for(int i=1;i<=11;i++){p.Screws[i]=Resources.Load<Sprite>(ReskinArt.Screw(i));p.Boxes[i]=Resources.Load<Sprite>(ReskinArt.Box(i));p.Lids[i]=Resources.Load<Sprite>(ReskinArt.Lid(i));}
            AssetDatabase.CreateAsset(p,PalettePath);return p;
        }
        static void Save(string name,Func<GameObject> factory)
        {
            string path=Widgets+"/"+name+".prefab";if(File.Exists(path))return;
            var go=factory();PrefabUtility.SaveAsPrefabAsset(go,path);UnityEngine.Object.DestroyImmediate(go);
        }
        static GameObject Instance(string name,Transform parent)=> (GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Widgets+"/"+name+".prefab"),parent);
        static RectTransform Layer(string name,Transform parent)
        {
            var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(parent,false);Center(r);return r;
        }
        static RectTransform Stretch(string name,Transform parent,Vector2 pivot)
        {
            var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(parent,false);r.pivot=pivot;r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;return r;
        }
        static Image ColorImage(string name,Transform parent,Rect r,Color color,bool raycast=false)
        {
            var image=Rect(name,parent,r.x,r.y,r.width,r.height).gameObject.AddComponent<Image>();image.color=color;image.raycastTarget=raycast;return image;
        }
        static Image PaletteImage(string name,Transform parent,Sprite sprite,Rect r,bool preserve=true)
        {
            var image=Rect(name,parent,r.x,r.y,r.width,r.height).gameObject.AddComponent<Image>();image.sprite=sprite;image.preserveAspect=preserve;image.raycastTarget=false;return image;
        }
        static Button SimpleButton(string name,Transform parent,Rect r,string label,ScrewKingUiCommand command)
        {
            var image=Pic(name,parent,ReskinArt.UI+"Layer 16 copy 2",r.x,r.y,r.width,r.height);image.preserveAspect=false;image.raycastTarget=true;
            Label("Label",image.transform,label,0,0,r.width,r.height,24,Color.white,new Color(.17f,.34f,.03f));
            var button=image.gameObject.AddComponent<Button>();button.targetGraphic=image;Wire(button,command);return button;
        }
        static GameObject Box(string name,bool closing)
        {
            var go=new GameObject(name,typeof(RectTransform),typeof(ScrewKingBoxView));var view=go.GetComponent<ScrewKingBoxView>();view.Palette=palette;
            var r=go.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(.5f,1);r.sizeDelta=new Vector2(145,175);r.anchoredPosition=new Vector2(375,-86);
            view.Motion=Stretch("Motion (animated)",r,new Vector2(.5f,0));
            view.Body=PaletteImage("Body",view.Motion,palette.Box(1),new Rect(0,0,145,175));view.Body.raycastTarget=true;
            view.LockedArt=Pic("LockedArtwork",view.Motion,ReskinArt.UI+"Layer 9",0,0,145,175);
            var click=ColorImage("UnlockButton",view.LockedArt.transform,new Rect(0,0,145,175),Color.clear,true);view.UnlockButton=click.gameObject.AddComponent<Button>();view.UnlockButton.targetGraphic=click;
            view.UnlockButton.gameObject.AddComponent<ScrewKingButtonFeedback>().Visual=view.LockedArt.rectTransform;
            UnityEventTools.AddPersistentListener(view.UnlockButton.onClick,view.Unlock);
            view.Seats=Rect("Seats",view.Motion,0,0,145,175).gameObject;view.Screws=new Image[3];
            for(int i=0;i<3;i++){
                float x=72.5f+(i==0?0:i==1?-30:30),y=i==0?56.5f:106.5f;
                Pic("SeatHole"+i,view.Seats.transform,ReskinArt.UI+"q copy 5",x-16,y-16,32,32);
                view.Screws[i]=PaletteImage("Screw"+i,view.Seats.transform,palette.Screw(1),new Rect(x-21.6f,y-21.6f,43.2f,43.2f));view.Screws[i].gameObject.SetActive(closing);
            }
            view.Lid=PaletteImage("Lid (animated)",view.Motion,palette.Lid(1),new Rect(-2,34,149,121));view.LidMotion=view.Lid.rectTransform;view.Lid.gameObject.SetActive(closing);
            view.LockedArt.gameObject.SetActive(false);return go;
        }
        static GameObject Buffer()
        {
            var go=new GameObject("HudBufferSlot",typeof(RectTransform),typeof(ScrewKingBufferSlotView));var view=go.GetComponent<ScrewKingBufferSlotView>();view.Palette=palette;
            var r=go.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(.5f,.5f);r.sizeDelta=new Vector2(44,46);r.anchoredPosition=new Vector2(375,-307.6f);
            view.PreviewModelPosition=new Vector2(0,359.4f);view.Motion=Stretch("Motion (layout from model)",r,new Vector2(.5f,.5f));
            var hole=Pic("Hole",view.Motion,ReskinArt.UI+"Layer 5 copy 4",0,0,44,46);hole.raycastTarget=true;
            view.Screw=PaletteImage("Screw",view.Motion,palette.Screw(1),new Rect(.4f,1.4f,43.2f,43.2f));view.Screw.gameObject.SetActive(false);return go;
        }
        static GameObject Flight()
        {
            var go=new GameObject("HudFlyingScrew",typeof(RectTransform),typeof(ScrewKingFlyingScrewView));Center(go.GetComponent<RectTransform>());var view=go.GetComponent<ScrewKingFlyingScrewView>();view.Palette=palette;
            view.Motion=new GameObject("Motion (from source animation)",typeof(RectTransform)).GetComponent<RectTransform>();view.Motion.SetParent(go.transform,false);view.Motion.anchorMin=view.Motion.anchorMax=view.Motion.pivot=new Vector2(.5f,.5f);view.Motion.sizeDelta=Vector2.zero;
            view.Lift=new GameObject("Lift (animated)",typeof(RectTransform)).GetComponent<RectTransform>();view.Lift.SetParent(view.Motion,false);view.Lift.anchorMin=view.Lift.anchorMax=view.Lift.pivot=new Vector2(.5f,.5f);view.Lift.sizeDelta=Vector2.zero;
            var body=Pic("BodyStretch (animated)",view.Lift,"Art/Screws/ScrewBack",-9,12,18,40);body.preserveAspect=false;view.BodyStretch=body.rectTransform;
            view.HeadRotation=new GameObject("HeadRotation (animated)",typeof(RectTransform)).GetComponent<RectTransform>();view.HeadRotation.SetParent(view.Lift,false);view.HeadRotation.anchorMin=view.HeadRotation.anchorMax=view.HeadRotation.pivot=new Vector2(.5f,.5f);view.HeadRotation.sizeDelta=new Vector2(54,54);
            view.Head=PaletteImage("Head",view.HeadRotation,palette.Screw(1),new Rect(0,0,54,54));return go;
        }
        static GameObject Guide()
        {
            var go=new GameObject("HudGuide",typeof(RectTransform),typeof(ScrewKingGuideView));Center(go.GetComponent<RectTransform>());var view=go.GetComponent<ScrewKingGuideView>();
            view.Motion=new GameObject("Motion (follows target)",typeof(RectTransform)).GetComponent<RectTransform>();view.Motion.SetParent(go.transform,false);view.Motion.anchorMin=view.Motion.anchorMax=view.Motion.pivot=new Vector2(.5f,.5f);view.Motion.sizeDelta=Vector2.zero;
            view.Circle=Pic("Circle",view.Motion,"Art/HUD/game_guide_circle",-43,-43,86,86).rectTransform;
            view.Hand=Pic("Hand",view.Motion,"Art/HUD/game_guide_hand",12,12,85,105).rectTransform;return go;
        }
        static GameObject Booster(string name,string icon,string label,ScrewKingUiCommand command)
        {
            bool slot=command==ScrewKingUiCommand.AddSlot,hammer=command==ScrewKingUiCommand.GlassHammer;
            var go=new GameObject(name,typeof(RectTransform));var r=go.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.sizeDelta=new Vector2(136.11f,159.03f);
            var click=go.AddComponent<Image>();click.color=Color.clear;var button=go.AddComponent<Button>();button.targetGraphic=click;button.transition=Selectable.Transition.None;Wire(button,command);
            Pic("ToolBase",r,ReskinArt.UI+"Layer 17 copy 2",4.86f,11.1f,134.03f,134.03f);
            if(slot)Pic("ToolIcon",r,ReskinArt.UI+icon,0,0,130.56f,131.25f);
            else if(hammer)Pic("ToolIcon",r,ReskinArt.UI+icon,0,-6.94f,142.36f,143.75f);
            else Pic("ToolIcon",r,ReskinArt.UI+icon,6.94f,-11.8f,132.64f,151.39f);
            Pic("VideoBadge",r,ReskinArt.UI+"Layer 18",slot?-11.1f:hammer?-15.3f:-1.4f,0,59.03f,45.14f);
            Pic("LabelBackground",r,ReskinArt.UI+"Layer 16 copy 2",0,107.64f,136.11f,51.39f);
            float sx=slot?.86f:hammer?1:.7f;
            var caption=Label("Label",r,hammer?"GLASS\nHAMMER":label,68.055f,133.335f,136.11f/sx,51.39f,hammer?28:34,Color.white,new Color(.17f,.34f,.03f));
            caption.font=Resources.Load<Font>("UI/Fonts/LilitaOne-Regular");caption.fontStyle=FontStyle.Italic;caption.lineSpacing=.78f;caption.rectTransform.pivot=new Vector2(.5f,.5f);caption.rectTransform.localScale=new Vector3(sx,1,1);
            if(hammer){var armed=ColorImage("ArmedHighlight",r,new Rect(0,107.64f,136.11f,51.39f),new Color(1,.8f,.2f,.45f));armed.gameObject.SetActive(false);}
            return go;
        }
        static void Build(ScrewKingGameplayHud hud)
        {
            var content=Layer("AuthoredHUD",hud.transform);
            var header=Rect("Header",content,0,0,750,90);
            SimpleButton("HomeButton",header,new Rect(24,22,106,48),"HOME",ScrewKingUiCommand.Quit).gameObject.SetActive(false);
            ColorImage("LevelBackground",header,new Rect(225,14,300,60),new Color(.48f,.20f,.035f,.85f),true);
            hud.LevelLabel=Label("LevelLabel",header,"LEVEL 1",205,14,340,60,38);
            var settings=Pic("SettingsButton",header,ReskinArt.UI+"Layer 12",644,12,78,78);settings.raycastTarget=true;var settingButton=settings.gameObject.AddComponent<Button>();settingButton.targetGraphic=settings;Wire(settingButton,ScrewKingUiCommand.Settings);
            var progress=Rect("Progress",content,0,0,750,420);progress.gameObject.SetActive(false);
            ColorImage("Track",progress,new Rect(180,370,390,10),new Color(.48f,.23f,.08f,.35f));
            hud.ProgressFill=ColorImage("Fill",progress,new Rect(180,370,390,10),new Color(.38f,.78f,.08f));hud.ProgressFill.sprite=SolidSprite();hud.ProgressFill.type=Image.Type.Filled;hud.ProgressFill.fillMethod=Image.FillMethod.Horizontal;hud.ProgressFill.fillOrigin=0;hud.ProgressFill.fillAmount=0;
            hud.BoxCounter=Label("BoxCounter",progress,"0 / 3 BOXES",240,384,270,30,19,new Color(.29f,.12f,.04f));
            var boxes=Layer("Boxes",content);hud.Boxes=new ScrewKingBoxView[4];float[] previewX={246,82,-82,-246};
            for(int i=0;i<4;i++){
                var view=Instance("HudBox",boxes).GetComponent<ScrewKingBoxView>();view.name="Box"+i;view.PreviewX=previewX[i];view.Motion.anchoredPosition=new Vector2(previewX[i],0);
                bool locked=i<2;view.Body.gameObject.SetActive(!locked);view.LockedArt.gameObject.SetActive(locked);view.Seats.SetActive(!locked);hud.Boxes[i]=view;
            }
            hud.ClosingLayer=Layer("ClosingBoxes",content);hud.ClosingBoxPrefab=AssetDatabase.LoadAssetAtPath<GameObject>(Widgets+"/HudClosingBox.prefab").GetComponent<ScrewKingBoxView>();
            var buffer=Layer("BufferSlots",content);hud.BufferSlots=new ScrewKingBufferSlotView[16];
            for(int i=0;i<16;i++){
                var view=Instance("HudBufferSlot",buffer).GetComponent<ScrewKingBufferSlotView>();view.name="Slot"+i;
                var point=i<5?new Vector2((i-2)*64,359.4f):i<8?new Vector2((i-3.5f)*64,359.4f):new Vector2(-224+(i-8)*64,317.8f);
                view.PreviewModelPosition=point;view.GetComponent<RectTransform>().anchoredPosition=new Vector2(375+point.x,-(667-point.y));view.gameObject.SetActive(i<5);hud.BufferSlots[i]=view;
            }
            hud.FlightLayer=Layer("FlyingScrews",content);hud.FlyingScrewPrefab=AssetDatabase.LoadAssetAtPath<GameObject>(Widgets+"/HudFlyingScrew.prefab").GetComponent<ScrewKingFlyingScrewView>();
            hud.Guide=Instance("HudGuide",content).GetComponent<ScrewKingGuideView>();hud.Guide.gameObject.SetActive(false);
            hud.HammerShade=ColorImage("HammerShade",content,new Rect(0,420,750,690),new Color(.1f,.07f,.02f,.12f)).gameObject;hud.HammerShade.SetActive(false);
            hud.NormalHint=Label("NormalHint",content,"Match three screws of the same color",50,1280,650,36,19,new Color(.29f,.12f,.04f)).gameObject;
            hud.HammerHint=Label("HammerHint",content,"Choose a board to break",50,1280,650,36,19,new Color(.29f,.12f,.04f)).gameObject;hud.HammerHint.SetActive(false);
            var boosters=Rect("Boosters",content,0,1163.8f,750,160);string[] names={"HudBoosterSlot","HudBoosterClear","HudBoosterHammer"};
            for(int i=0;i<3;i++){
                var instance=Instance(names[i],boosters);instance.GetComponent<RectTransform>().anchoredPosition=new Vector2(new[]{88.2f,303.5f,534f}[i],0);
                if(i==2)hud.HammerHighlight=instance.transform.Find("ArmedHighlight").gameObject;
            }
            hud.MessagePanel=Rect("Message",content,30,1052,690,80).gameObject;ColorImage("Background",hud.MessagePanel.transform,new Rect(0,0,690,80),new Color(1,.98f,.84f,.96f));hud.MessageLabel=Label("MessageLabel",hud.MessagePanel.transform,"",10,0,670,80,28,new Color(.29f,.12f,.04f));hud.MessageLabel.fontStyle=FontStyle.Bold;hud.MessagePanel.SetActive(false);
            var transition=ColorImage("Transition",content,new Rect(0,0,750,1334),new Color(.12f,.07f,.03f));hud.Transition=transition.gameObject.AddComponent<CanvasGroup>();hud.Transition.alpha=0;hud.Transition.blocksRaycasts=false;transition.gameObject.SetActive(false);
        }
    }
}
